L.append(T(3825469,"Tumisan Daging Sapi","Hidangan ini tinggi protein sehingga cocok sebagai makan malam bagi penderita yang menjalani dialisis.","4",None,
["500 g steak daging sapi, rump atau sirloin","1 paprika hijau","4 daun bawang","1-2 siung bawang putih, dimemarkan","4 batang seledri","1 paprika merah","2-3 sendok teh bubuk cabai ringan","2 sendok makan paprika bubuk","1 kubus kaldu daging sapi sangat rendah garam atau tanpa garam","60 ml air mendidih","2 sendok makan madu bening","2 sendok makan cuka anggur merah","2 sendok makan minyak bunga matahari","1 sendok makan saus Worcestershire","250 g beras basmati mentah, dibilas dan ditiriskan."],
["Potong daging sapi menjadi irisan 1 cm dan masukkan ke dalam mangkuk. Tambahkan paprika bubuk dan bubuk cabai, lumuri daging secara merata. Diamkan untuk dimarinasi selama 1 jam. Aduk setelah 30 menit dan periksa apakah daging sudah terlumuri dengan baik.","Masukkan beras ke dalam panci dan tuang 500 ml air. Didihkan hingga mendidih kuat dan kecilkan api hingga mendidih perlahan. Masak selama 12 menit.","Potong seledri dan paprika menjadi potongan sepanjang 5 cm lalu menjadi irisan setebal sekitar 5 mm. Iris tipis daun bawang dan sisihkan.","Panaskan minyak dalam wok atau wajan besar dan tumis daun bawang, bawang putih, seledri, dan paprika selama satu menit sebelum memasukkan steak. Lanjutkan menumis dengan api besar selama 3-4 menit.","Buat saus dengan menambahkan satu kubus kaldu ke dalam 60 ml air mendidih dan menambahkan saus Worcestershire, madu, dan cuka anggur merah. Masukkan saus dan masak sampai daging terlumuri dengan baik.","Tiriskan nasi dan bilas dengan air mendidih, sajikan segera."],
[g("chef","Buat tumisan lezat bergaya Asia ini dengan daging sapi yang empuk. Sempurna untuk makan malam di hari kerja yang sibuk atau dibuat lebih dulu dan dibekukan."),g("carb","Sumber utama karbohidrat dalam hidangan ini adalah nasi. Namun, madu juga akan menambah karbohidrat hidangan ini. Nilai karbohidrat diberikan bagi mereka yang terlatih dalam penyesuaian insulin."),g("kp","Jika Anda telah diresepkan pengikat fosfat, pastikan Anda meminumnya bersama hidangan ini."),g("prot","Resep ini sangat tinggi protein yang sangat baik bagi orang yang menjalani dialisis. Jika Anda dianjurkan mengurangi asupan protein, makanlah daging sapi dalam porsi yang lebih kecil."),g("gf","Gunakan kubus kaldu bebas gluten dan sajikan dengan nasi."),g("veg","Daging sapi dapat diganti dengan protein vegetarian seperti tahu atau potongan Quorn agar sesuai dengan diet vegetarian."),g("vegan","Ganti daging sapi dengan tahu atau alternatif vegan, hilangkan madu dan gunakan satu sendok makan golden syrup sebagai gantinya."),g("cheap","Ganti daging sapi dengan kalkun atau tahu untuk hidangan yang sama lezatnya tetapi lebih murah."),g("store","Bekukan sisa tumisan daging sapi tetapi kami tidak menyarankan membekukan nasi. Untuk mencairkan, buka tutup wadah dan biarkan di lemari es agar mencair perlahan. Panaskan kembali hingga benar-benar panas dalam wok, wajan, atau microwave Anda.")],
[]))
L.append(T(3853426,"Semur Kacang",">","2",None,
["100 g wortel, dikupas dan dicincang","1 kubus kaldu sayuran rendah garam dilarutkan dengan 300 ml air mendidih","400 g kacang putih kalengan (jenis apa pun) dibilas dan ditiriskan","2 sendok makan pasta tomat","1 sendok teh campuran rempah kering","100 g kacang polong beku",("Untuk penyajian","Lada hitam"),("Untuk penyajian","50 g keju cheddar parut"),("Untuk penyajian","2 iris tebal roti atau 2 roti gulung renyah")],
["Masukkan wortel ke dalam panci dan tutupi dengan kaldu mendidih. Didihkan perlahan selama 4 menit.","Masukkan kacang yang sudah ditiriskan, pasta tomat, dan campuran rempah lalu aduk.","Kecilkan api dan didihkan perlahan selama 20 menit, lalu tambahkan kacang polong beku dan masak 3-5 menit lagi.","Sajikan dalam 2 mangkuk bersama roti dan bumbui dengan lada hitam. Taburkan keju parut."],
[g("chef","Hidangan vegetarian bergizi dan tinggi protein yang juga rendah kalium dan fosfat."),g("carb","Roti adalah sumber utama karbohidrat dalam hidangan utama ini, namun kacang juga akan menjadi sumber karbohidrat. Nilainya diberikan bagi mereka yang terlatih dalam penyesuaian insulin."),g("pk2","Hidangan ini rendah kalium; jika Anda dianjurkan menjalani diet rendah kalium, pastikan Anda mengikuti takaran yang tercantum. Resep ini rendah fosfat, namun tetap mengandung sedikit fosfat, karena kacang dan keju, sehingga jika Anda telah diresepkan pengikat fosfat, pastikan Anda meminumnya bersama hidangan ini."),g("prot","Hidangan ini tinggi protein dan karena itu cocok bagi mereka yang menjalani dialisis. Jika Anda dianjurkan makan lebih sedikit protein, Anda mungkin ingin mengganti kacang polong dengan jagung manis dan/atau mengurangi jumlah keju menjadi 30 g.")],
[]))
L.append(T(3905574,"Salmon Panggang Oven ala Karibia dengan Sayuran Tumis","Resep rendah kalium dan rendah fosfat dengan sensasi pedas. Sajikan dengan nasi untuk membuat hidangan seimbang.","4",None,
[("Salmon","4 fillet salmon (masing-masing sekitar 120 g)"),("Salmon","1 lemon"),("Salmon","1 batang seledri"),("Salmon","250 g kubis putih"),("Salmon","½ paprika hijau"),("Salmon","½ paprika merah"),("Salmon","½ paprika kuning"),("Salmon","1 wortel"),("Salmon","2 sendok makan minyak sayur"),("Bumbu hijau Karibia","2 daun bawang, dipangkas"),("Bumbu hijau Karibia","1 cabai scotch bonnet"),("Bumbu hijau Karibia","3 siung bawang putih"),("Bumbu hijau Karibia","Segenggam timi segar atau timi lemon"),("Bumbu hijau Karibia","Segenggam ketumbar segar"),("Bumbu hijau Karibia","Segenggam kemangi segar"),("Bumbu hijau Karibia","1 bawang bombai besar, dikupas dan dicincang"),("Bumbu hijau Karibia","1 batang seledri, dicincang")],
["Buat bumbu hijau Karibia dengan memblender daun bawang, scotch bonnet, bawang putih, timi, ketumbar, kemangi, bawang bombai, dan seledri dalam food processor. Letakkan salmon dalam mangkuk dan bersihkan dengan lemon. Tambahkan 2 sendok makan bumbu dan campur. Diamkan di lemari es semalaman, atau setidaknya satu jam sebelum dimasak.","Panaskan oven hingga 190°C/ 170°C fan /gas mark 5. Letakkan salmon dalam loyang yang diolesi lemak dan siram dengan sedikit minyak. Tutup dengan aluminium foil dan masak selama 20 menit. Isi panci besar dengan air dan didihkan. Siapkan sayuran Anda dengan mengiris halus seledri, kubis putih, paprika, dan wortel.","Buka aluminium foil yang menutupi salmon lalu masak 10 menit lagi sampai sedikit kecokelatan. Selama 10 menit terakhir itu, rebus sayuran yang diiris dalam banyak air sampai sedikit lunak lalu tiriskan.","Tumis sayuran rebus dalam 2 sendok makan minyak selama 3 menit dalam wajan, tambahkan sedikit bumbu Karibia untuk rasa. Sajikan salmon di atas alas sayuran tumis."],
[g("chef","Bumbu hijau Karibia adalah saus atau pasta serbaguna yang sering digunakan di seluruh pulau-pulau Karibia. Marinasi ikan dan tambahkan ke sayuran untuk memberikan banyak rasa."),g("carb","Resep ini rendah karbohidrat dan nilainya diberikan bagi mereka yang terlatih dalam penyesuaian insulin. Untuk menjadikannya hidangan yang lebih seimbang, sajikan dengan nasi atau porsi kecil pai tepung jagung."),g("kp","Ikan tanpa tulang yang digunakan di sini membantu menjaga fosfat tetap rendah. Jika Anda telah diresepkan pengikat fosfat, pastikan Anda meminumnya bersama hidangan ini. Merebus sayuran terlebih dahulu mengurangi kandungan kaliumnya. Jika Anda tidak memerlukan diet rendah kalium, Anda dapat menumis sayuran langsung dari keadaan mentah. Bumbu hijau mengandung bahan mentah dan karena itu lebih tinggi kalium sehingga hanya boleh digunakan dalam jumlah kecil."),g("prot","Ikan adalah sumber protein rendah lemak yang sangat baik. Fillet ikan kakap laut (sea bream) atau bass laut juga cocok dengan hidangan ini sebagai alternatif."),g("cheap","Anda dapat menggunakan ikan beku untuk mengurangi biaya (cairkan sepenuhnya di lemari es sebelum dimasak)."),g("store","Jika Anda menambahkan satu sendok makan cuka sari apel ke bumbu hijau, bumbu dapat dibuat lebih dulu dan disimpan di lemari es hingga lima hari."),g("tips","Tambahkan 2 cabai scotch bonnet ke bumbu hijau Karibia Anda jika Anda suka pedas!\nJika Anda menjalani transplantasi, Anda sebaiknya membeli ikan dalam kemasan, bukan dari penjual ikan atau konter deli ikan, untuk menghindari risiko kontaminasi bakteri.")],
[]))
L.append(T(3915498,"Ayam dan Paprika Satu Panci",">","2",None,
["2 paha ayam (150-160 g), kulit dibuang","1 sendok makan pencuci mulut (10 ml) minyak zaitun","1 paprika merah, dipotong 3 cm","1 paprika hijau, dipotong 3 cm","1 bawang merah kecil (shallot), dicincang halus","1 siung bawang putih, dicincang","2 cabai merah, diiris dan dibuang bijinya","150 g pasta orzo","1 sendok makan pencuci mulut (10 ml) paprika bubuk manis","250 ml kaldu ayam rendah garam","75 g tomat ceri","Lada hitam","Segenggam kecil peterseli, dicincang (opsional)","10 g crème fraîche (opsional)"],
["Panaskan oven terlebih dahulu hingga 190°C / fan 170°C / gas mark 5. Masukkan minyak zaitun ke dalam wadah casserole tahan api dan letakkan di atas kompor dengan api sedang. Bumbui ayam dengan lada hitam dan masak sampai tersegel di setiap sisi. Pindahkan ke piring untuk nanti.","Masukkan paprika ke dalam wadah dan masak selama 3 hingga 4 menit, lalu tambahkan bawang merah kecil, bawang putih, dan cabai. Masak 5 menit lagi sampai lunak. Aduk orzo dan paprika bubuk.","Tuang kaldu dan tambahan 200 ml air mendidih untuk menutupi orzo sepenuhnya. Letakkan ayam dan tomat di atas orzo dan panggang dalam oven selama 30 menit.","Sajikan dalam mangkuk, dengan crème fraîche dan peterseli cincang di atasnya jika diinginkan."],
[g("chef","Hidangan makan malam di tengah pekan yang mudah, cocok untuk semua tahap penyakit ginjal."),g("carb","Orzo (pasta) adalah sumber utama karbohidrat dalam resep ini, dan nilainya diberikan bagi mereka yang terlatih dalam penyesuaian insulin."),g("kp","Resep ini rendah kalium, jika mengikuti takaran dalam daftar bahan dan ukuran penyajian. Resep ini juga rendah fosfat, namun tetap mengandung sedikit fosfat, terutama dari ayam, jadi jika Anda telah diresepkan pengikat fosfat, minumlah sesuai petunjuk."),g("prot","Resep ini tinggi protein, sehingga cocok bagi mereka yang dianjurkan makan lebih banyak protein, seperti mereka yang menjalani dialisis. Jika Anda dianjurkan makan lebih sedikit protein, Anda mungkin ingin mengurangi ayam dan menambahkan satu kaleng kacang arab. Ini juga akan menurunkan kandungan kalium dan fosfat."),g("store","Hidangan ini paling enak dimakan saat baru dibuat."),g("tips","Beras mentah dapat digunakan sebagai pengganti orzo jika supermarket Anda tidak menyediakannya.")],
[]))
L.append(T(3931679,"Kari Sayuran Karibia","Kari yang creamy, rendah protein, dan penuh sayuran yang rendah garam, kalium, dan fosfat.","4",None,
["1 sendok makan minyak","1 sendok makan bubuk kari","1 sendok makan kunyit","1 bawang bombai, dicincang","1 cm akar jahe, dikupas & dicincang halus","4 siung bawang putih, dicincang","100 g buncis, dicincang","1 paprika merah, dicincang","2 batang seledri, dicincang","1 kaleng 400 g kacang arab, ditiriskan","1 kaleng 200 g jagung manis, ditiriskan","2 sendok makan bumbu hijau, atau 1 sendok makan campuran rempah","4 sendok makan yoghurt tawar","4-6 roti pita gandum utuh, roti, roti naan atau chapati",("Untuk penyajian","4 sendok makan yoghurt tawar"),("Untuk penyajian","10 g ketumbar segar")],
["Panaskan wajan besar dengan api sedang dan tambahkan minyak. Setelah minyak panas, masukkan bubuk kari dan kunyit, aduk dalam wajan lalu tambahkan bawang bombai, bawang putih, dan jahe yang dicincang. Aduk dan masak perlahan sampai bawang bombai sedikit lunak.","Ketika bawang bombai sudah lunak, tambahkan kacang arab yang ditiriskan, buncis, paprika merah, seledri, dan jagung manis.","Tambahkan bumbu hijau ke kari dengan 200 ml air dan didihkan perlahan dengan api kecil selama 5-10 menit. Tambahkan yoghurt, aduk dan didihkan lagi dengan api kecil selama 1 menit.","Setelah kari siap, panggang roti pita (atau siapkan roti, naan, atau chapati). Sajikan dalam empat mangkuk dengan roti pilihan Anda, yoghurt, dan ketumbar cincang."],
[g("chef","Kari calypso yang cepat dan sangat hemat, dibuat dalam satu panci agar cucian minimal!"),g("carb","Roti pita, naan, atau chapati adalah sumber utama karbohidrat dalam resep ini, dan nilainya diberikan bagi mereka yang terlatih dalam penyesuaian insulin."),g("kp","Resep ini rendah kalium, jika mengikuti takaran dalam daftar bahan dan ukuran penyajian. Karena itu, cocok bagi mereka yang dianjurkan mengurangi kalium dalam diet mereka.\nResep ini juga rendah fosfat, namun tetap mengandung sedikit fosfat, terutama dari kacang arab, roti pita, dan yoghurt, sehingga jika Anda telah diresepkan pengikat fosfat, minumlah sesuai petunjuk."),g("prot","Resep ini rendah protein, sehingga cocok bagi mereka yang dianjurkan makan lebih sedikit protein."),g("gf","Gunakan roti pita, naan, atau chapati bebas gluten."),g("vegan","Gunakan yoghurt vegan, seperti dari kedelai."),g("store","Setelah dimasak dan dingin, resep ini dapat disimpan dalam wadah kedap udara di lemari es dan dipanaskan kembali pada hari berikutnya.")],
[]))
L.append(T(3934642,"Keju Brokol-Kembang Kol","Sentuhan sederhana pada kembang kol keju, dibuat dengan kembang kol dan brokoli. Hidangan ini menyediakan sumber protein dan rendah kalium, fosfat, dan garam jika dinikmati dalam ukuran porsi yang dianjurkan.","4 porsi dewasa",None,
["1 kepala kembang kol kecil, dipecah menjadi kuntum","1 kepala brokoli kecil, dipecah menjadi kuntum","200 g krim keju lunak","150 ml susu (setengah skim, murni atau skim)","50 g keju Cheddar, diparut","1 sendok teh mustard Inggris (atau Dijon jika lebih suka)",("Untuk penyajian","2 baguette setengah matang (kemasan 300 g berisi 2 baguette)"),("Untuk penyajian","40 g mentega tawar, dilunakkan"),("Untuk penyajian","1 sendok teh pasta bawang putih"),("Untuk penyajian","1 sendok teh peterseli kering")],
["Panggang baguette sesuai petunjuk lalu sisihkan hingga dingin.","Panaskan oven terlebih dahulu hingga 180°C / 160°C fan / gas mark 4. Masukkan kembang kol dan brokoli ke dalam panci berisi air dan didihkan lalu masak sekitar 5 menit sampai sayuran hampir empuk. Angkat dari api dan tiriskan.","Buat saus dengan memanaskan krim keju dengan api sedang untuk mengencerkannya lalu kocok susu hingga tercampur sepenuhnya menjadi saus bersama gilingan lada hitam secukupnya dan mustard Inggris. Angkat dari api.","Tata kembang kol dan brokoli dalam loyang pemanggang dan tuang saus keju. Taburkan Cheddar parut di atasnya lalu masak dalam oven selama 25 menit sampai keemasan cantik.","Selagi memasak, buat mentega bawang putih dengan mencampur mentega dengan pasta bawang putih dan rempah kering, kocok hingga rata. Belah dua baguette yang sudah matang dan oleskan dengan mentega bawang putih. Satukan kembali kedua belahan baguette dan bungkus dengan aluminium foil. Masukkan ke dalam oven bersama kembang kol keju saat waktu memasak tersisa 10 menit."],
[g("chef","Sentuhan baru pada hidangan klasik keluarga"),g("portchild","Ukuran penyajian didasarkan pada porsi dewasa. Berikut panduan untuk anak-anak:\nBalita (usia 1-4): ¼\nAnak kecil (usia 5-9): ½\nAnak yang lebih besar (usia 10-13): ¾\nRemaja (14+): 1\n"+CH),g("carb","Baguette adalah sumber utama karbohidrat dalam resep ini, dan nilainya diberikan bagi mereka yang terlatih dalam penyesuaian insulin."),g("energy","Jika Anda perlu menaikkan berat badan, memiliki anak yang sedang tumbuh dan membutuhkan lebih banyak kalori, atau nafsu makan Anda kurang, Anda dapat menggunakan susu murni untuk membuat saus keju dan menambahkan mentega ekstra pada roti bawang putih."),g("prot","Resep ini menyediakan sumber protein tetapi tidak tinggi protein. Jika Anda dianjurkan makan lebih banyak protein, pastikan untuk menyertakan makanan yang lebih tinggi protein pada waktu makan dan camilan lainnya sepanjang hari."),g("pk","Resep ini rendah kalium, jika mengikuti takaran dalam daftar bahan dan ukuran penyajian. Karena itu, cocok bagi mereka yang dianjurkan makan lebih sedikit kalium.\nResep ini juga rendah fosfat, namun tetap mengandung sedikit fosfat, terutama dari susu dan keju, sehingga jika Anda telah diresepkan pengikat fosfat, minumlah sesuai petunjuk."),g("gf","Gunakan baguette bebas gluten."),g("vegan","Gunakan alternatif vegan untuk krim keju, susu, dan Cheddar."),g("health","Untuk mengurangi lemak jenuh dan menambah serat, pertimbangkan menggunakan susu rendah lemak, krim keju rendah lemak, dan memilih baguette gandum utuh."),g("cheap","Resep ini dibuat dengan biaya serendah mungkin, namun krim keju dapat diganti dengan alternatif merek sendiri supermarket, bawang putih segar dapat digunakan sebagai pengganti pasta bawang putih, dan peterseli kering dapat dihilangkan."),g("store","Sisa makanan dapat disimpan di lemari es hingga 2 hari dan dipanaskan kembali. Kembang kol keju dapat dibuat sehari sebelumnya dan disimpan di lemari es semalaman, lalu dimasak.")],
[]))
L.append(T(3936001,"Fillet Ikan Cod Panggang, Tabouli, dan Salsa Tomat","Hidangan tinggi protein, rendah kalium, fosfat, dan garam. Sempurna bagi mereka yang menjalani dialisis.","4",None,
[("Fillet ikan cod","300 g fillet ikan cod, tanpa kulit"),("Fillet ikan cod","25 g keju cheddar"),("Fillet ikan cod","1 sendok makan remah roti putih segar"),("Fillet ikan cod","Sejumput lada hitam yang baru digiling"),("Fillet ikan cod","1 sendok makan campuran rempah segar"),("Fillet ikan cod","1 sendok teh minyak zaitun"),("Tabouli","225 g couscous"),("Tabouli","220 ml air mendidih"),("Tabouli","3 sendok makan air perasan lemon"),("Tabouli","1 sendok makan minyak zaitun"),("Tabouli","2 siung bawang putih"),("Tabouli","25 g daun mint segar"),("Tabouli","25 g ketumbar segar"),("Tabouli","25 g dill segar"),("Tabouli","60 g tomat plum"),("Tabouli","50 g mentimun"),("Tabouli","25 g daun bawang"),("Tabouli","Sejumput lada hitam yang baru digiling"),("Salsa tomat","65 g tomat matang,"),("Salsa tomat","½ cabai merah"),("Salsa tomat","½ sendok makan campuran rempah segar"),("Salsa tomat","Sejumput lada hitam yang baru digiling")],
["Tuang air mendidih ke atas couscous. Tutup selama 10-12 menit sampai terserap. Cincang halus bawang putih, cincang rempah, dan buang biji serta potong dadu tomat dan mentimun. Gemburkan dengan garpu dan aduk minyak zaitun, air perasan lemon, dan bawang putih. Aduk tomat, mentimun, dan daun bawang. Bumbui dengan lada dan diamkan selama 1 jam dengan ditutup plastik wrap.","Untuk menyiapkan lapisan rempah bagi ikan cod, parut keju dan campurkan dalam mangkuk dengan remah roti dan rempah. Bumbui dengan lada, lalu dinginkan selama 30 menit agar campuran mengeras.","Panaskan oven terlebih dahulu hingga 200°C / 180°C / gas mark 6. Ketika sudah mengeras, giling campuran lapisan di antara 2 lembar kertas roti, potong menjadi persegi yang cukup besar untuk menutupi potongan ikan cod. Tekan perlahan agar menempel. Olesi loyang dengan minyak zaitun dan letakkan ikan cod. Panggang selama 6-8 menit sampai ikan cod baru matang.","Untuk membuat salsa, cincang tomat dan buang biji serta cincang halus cabai. Masukkan ke dalam mangkuk dan tambahkan rempah. Bumbui dengan lada dan campur sampai tercampur rata. Untuk menyajikan, letakkan sepotong ikan cod berlapis rempah di setiap piring, sendokkan salsa di sekeliling ikan cod dan sajikan dengan tabouli di sampingnya."],
[g("chef","Hidangan ikan segar yang menyenangkan dengan tabouli berbumbu rempah yang lezat di sampingnya."),g("carb","Couscous dan remah roti adalah sumber utama karbohidrat dalam hidangan utama ini dan nilainya diberikan bagi mereka yang terlatih dalam penyesuaian insulin."),g("kp","Hidangan ini memang mengandung bahan yang tinggi kalium dan fosfat. Namun, takarannya dijaga seminimal mungkin dan dengan menggunakan takaran yang tercantum dan mengikuti ukuran penyajian yang dianjurkan, kandungan fosfat dan kalium keseluruhan hidangan tetap rendah. Jika Anda telah diresepkan pengikat fosfat, pastikan Anda meminumnya bersama hidangan ini."),g("prot","Ikan dalam resep ini menyediakan sumber protein yang baik, ideal bagi mereka yang menjalani dialisis."),g("gf","Sajikan dengan nasi, quinoa, atau pasta bebas gluten sebagai pengganti couscous. Gunakan remah roti bebas gluten."),g("vv","Aduk 400 g kacang arab kalengan yang ditiriskan ke dalam tabouli dan sajikan dengan salsa."),g("cheap","Pilih fillet ikan yang lebih murah, fillet beku, atau ikan yang sedang diskon untuk mengurangi biaya. Anda dapat membeli remah roti kemasan atau menghemat uang dengan membuatnya sendiri. Untuk menghemat uang, gunakan satu sendok teh campuran rempah kering sebagai alternatif rempah segar pada lapisan ikan cod."),g("store","Ikan sebaiknya dimakan pada hari dimasak. Tabouli dan salsa dapat disimpan dalam wadah kedap udara di lemari es hingga dua hari."),g("tips","Bagi yang menjalani transplantasi, sebaiknya beli ikan dalam kemasan. Pilihan yang baik untuk campuran rempah segar termasuk kemangi, kucai, atau peterseli. Sebagai tambahan, gunakan sedikit mint, ketumbar, dan dill ekstra untuk melengkapi tabouli.")],
[]))
L.append(T(3959701,"Wrap Kalkun Asia","Juga cocok untuk bekal makan siang yang sehat.","2",None,
["1 sendok makan minyak zaitun","½ bawang merah, dicincang halus","150 g daging kalkun cincang tanpa lemak","1 siung bawang putih, dicincang halus","1 cabai merah, diiris halus","100 g wortel, dikupas dan dipotong menjadi irisan halus","1 sendok makan kecap asin rendah garam","Segenggam ketumbar, dicincang kasar","Segenggam kecil mint, dicincang kasar","2 jeruk nipis, diperas","50 g kacang arab, ditiriskan dan dikeringkan dengan kertas dapur","1 sendok teh biji jintan","2 tortilla wrap gandum utuh","6 daun bawang, dicincang halus","70 g selada serut"],
["Panaskan setengah minyak dalam wajan dengan api sedang dan tumis bawang sampai lunak. Masukkan kalkun, bawang putih, dan cabai lalu masak sampai kalkun matang, sekitar 10 menit. Masukkan wortel dan masak 5 menit lagi. Tiriskan kelebihan cairan dari wajan dan matikan api.","Tambahkan kecap asin, ketumbar, mint, dan air perasan jeruk nipis ke dalam campuran kalkun dan sisihkan agar rasanya berkembang.","Panaskan sisa minyak dalam panci terpisah dengan api besar dan masukkan kacang arab dan biji jintan. Masak sampai renyah; terus gerakkan agar tidak gosong.","Hangatkan tortilla wrap. Bagi campuran kalkun sama rata di antara kedua wrap. Taburi dengan daun bawang cincang, kacang arab, dan selada. Tutup dan gulung wrap untuk disajikan."],
[g("chef","Ini adalah wrap yang lezat, sehat, dan tinggi protein."),g("carb","Tortilla wrap gandum utuh adalah sumber utama karbohidrat dalam resep ini, dan nilainya diberikan bagi mereka yang terlatih dalam penyesuaian insulin."),g("kp","Resep ini rendah kalium, jika mengikuti takaran dan ukuran penyajian yang diberikan. Ini cocok bagi mereka yang dianjurkan mengurangi kalium dalam diet mereka. Resep ini juga rendah fosfat, namun tetap mengandung sedikit fosfat, terutama dari daging kalkun cincang dan kacang arab, jadi jika Anda telah diresepkan pengikat fosfat, minumlah sesuai petunjuk."),g("prot","Resep ini tinggi protein, sehingga cocok bagi mereka yang dianjurkan makan lebih banyak protein, seperti mereka yang menjalani dialisis. Jika Anda dianjurkan makan lebih sedikit protein, Anda mungkin ingin mengurangi jumlah daging kalkun cincang dan menambahkan kacang arab kalengan yang ditiriskan di atasnya."),g("tips","Ini juga dapat menjadi hidangan cepat pada hari yang sibuk dengan menyiapkan isian sebelumnya (dinginkan setelah langkah 1 dan simpan di lemari es hingga 3 hari, lalu hangatkan isian dan ikuti resep dari langkah 2). Juga cocok untuk bekal makan siang yang sehat.")],
[]))
L.append(T(3967979,"Cheesecake Panggang Blueberry dan Elderflower","Cocok untuk suguhan mewah sesekali, cita rasa blueberry dan elderflower yang halus dapat dinikmati dalam diet rendah kalium.","12",None,
["200 g biskuit digestive","190 g mentega tawar","600 g krim keju rendah lemak","150 g gula kastor","120 g blueberry","80 g tepung maizena","4 telur besar","70 ml sirup elderflower","284 ml krim kental (double cream)",("Untuk penyajian","Gula halus")],
["Panaskan oven terlebih dahulu hingga 175°C / 155°C fan / gas mark 4. Alasi loyang spring-form bulat 23 cm dengan kertas roti, haluskan bagian tepinya. Hancurkan biskuit digestive menjadi remah halus, lelehkan 40 g mentega tawar dan campurkan. Tekan campuran remah dengan kuat ke dasar loyang.","Kocok sisa 150 g mentega tawar dan gula kastor sampai lembut, tambahkan krim keju dan kocok sampai mengembang. Aduk tepung maizena.","Kocok telur, krim, dan sirup elderflower. Campur rata dan tuang campuran ke dalam loyang. Tekan blueberry ke dalam campuran agar tersebar merata dan tepat di bawah permukaan.","Panggang dalam oven selama satu jam. Biarkan dingin, lalu diamkan di lemari es semalaman agar mantap. Keluarkan dari lemari es, tunggu 30 menit sebelum dikeluarkan dari loyang dan ayak sedikit gula halus untuk menghias."],
[g("chef","Cobalah cheesecake yang sangat mewah ini. Buat sehari sebelumnya sehingga sempurna untuk disajikan sebagai makanan penutup saat teman-teman berkunjung. Anda juga dapat membekukannya dalam porsi untuk suguhan sesekali."),g("carb","Sumber utama karbohidrat dalam hidangan ini berasal dari gula, biskuit digestive, tepung maizena, dan sirup. Nilai karbohidrat diberikan bagi mereka yang terlatih dalam penyesuaian insulin."),g("kp","Krim keju cenderung lebih rendah fosfat daripada keju keras tetapi karena resep ini menggunakan krim keju dalam jumlah besar, resep ini tinggi fosfat. Jika Anda telah diresepkan pengikat fosfat, pastikan Anda meminumnya bersama hidangan ini.\nBlueberry adalah buah rendah kalium yang menambah warna dan rasa pada makanan penutup ini. Dengan mematuhi ukuran porsi yang dianjurkan dalam resep, kandungan kalium keseluruhan tetap rendah."),g("prot","Keju dan telur adalah sumber protein yang sangat baik, ideal jika Anda menjalani dialisis tetapi mungkin tidak cocok jika Anda dianjurkan menjalani diet protein lebih rendah."),g("gf","Gunakan biskuit digestive bebas gluten."),g("health","Cheesecake tinggi lemak dan gula dan sebaiknya disimpan untuk acara istimewa atau sebagai suguhan. Jika Anda ingin mengurangi jumlah gula atau lemak dalam resep ini, Anda dapat menggunakan olesan rendah lemak sebagai pengganti mentega, memilih biskuit digestive rendah gula (jika tersedia) atau menggunakan sirup bebas gula/tanpa tambahan gula."),g("cheap","Pilihan yang lebih murah adalah menggunakan blueberry beku tetapi jangan dicairkan sebelum digunakan."),g("store","Simpan dalam wadah kedap udara di lemari es dan makan dalam dua hari. Anda dapat dengan mudah membekukan cheesecake ini hingga 2 bulan. Tutup rapat dan bekukan dalam porsi. Cairkan semalaman di lemari es sebelum disajikan.")],
[]))
L.append(T(4000258,"Salmon Berbumbu","Perpaduan Cita Rasa","4",None,
["½ cangkir minyak zaitun (untuk marinade)","2 sendok makan minyak zaitun (untuk memasak)","¼ cangkir air perasan lemon","1 sendok makan cuka putih","1 sendok makan madu","4 sendok teh bawang putih cincang halus","4 sendok teh jahe cincang halus","¼ sendok teh paprika bubuk","½ sendok teh jintan","½ sendok teh lada atau bubuk cabai","1/8 sendok teh garam","2 fillet salmon (masing-masing 6 ons)"],
["Siapkan marinade: masukkan minyak zaitun, air perasan lemon, cuka, madu, dan rempah ke dalam mangkuk pencampur lalu kocok hingga tercampur.","Iris setiap fillet salmon memanjang untuk membuat 4 potong salmon terpisah masing-masing 3 ons. Masukkan salmon ke dalam mangkuk, pastikan semua salmon terlumuri marinade.","Tutup mangkuk dan dinginkan di lemari es selama 30-60 menit, lalu keluarkan dari lemari es dan diamkan pada suhu ruang selama 10 menit.","Panaskan minyak dalam wajan besar dengan api sedang-besar. Letakkan fillet salmon dalam wajan dan masak sekitar 4 menit di setiap sisi, atau sampai salmon mencapai 145⁰ F."],
[],[]))
